   "path": "exercises/vim-yank-word-001.yaml",
   "text": "schemaVersion: 1\n\nid: vim-yank-word-001\nslug: vim.yank.word-001\n\ntitle: \"Copy a word and paste it\"\ninstruction: \"Make it hello hello world by copying the first word.\"\n\nskillIds:\n  - vim.operator.yank\n\nmode: learn\ndifficulty: 2\n\nenvironment:\n  type: simulator\n  profile: vim-basic-v1\n\n# Cursor positions in content are 1-based (line, column), as in Vim's ruler.\ninitialState:\n  buffer: |\n    hello world\n  cursor:\n    line: 1\n    column: 1\n  vimMode: normal\n\nobjective:\n  type: buffer_equals\n  target: |\n    hello hello world\n\nsolutions:\n  - sequence: \"ywP\"\n    classification: optimal\n\nevaluation:\n  requireFinalNormalMode: true\n\nantiPatterns:\n  - insert_mode_navigation\n\nhints:\n  - afterMs: 4000\n    level: 1\n    text: \"y yanks (copies) just like d deletes. P puts before the cursor.\"\n  - afterMs: 8000\n    level: 2\n    text: \"yw, then P.\"\n\nmetadata:\n  language: text\n  context: prose\n  estimatedSeconds: 10\n  transferTags: []\n\nexplanation: \"yw copies from the cursor to the start of the next word, that is hello and its space. P puts it before the cursor, in front of the original hello, giving hello hello world. p would paste after the h and give hhello ello world.\"\n"
